/* eslint-disable react/prop-types */
import React, { useEffect, useMemo, useState } from 'react';
import { Helmet } from 'react-helmet-async';
import { useNavigate, useLocation } from 'react-router-dom';
import {
  Card,
  Table,
  Stack,
  Paper,
  Avatar,
  Button,
  TableRow,
  TableBody,
  TableCell,
  Typography,
  IconButton,
  TableContainer,
  TablePagination,
  MenuItem,
  Popover,
  Box,
} from '@mui/material';
import DateFormat from '../../components/dayjsFormat/DateFormat';
import { axios } from '../../utils/axios';
// components
import Iconify from '../../components/iconify';
import Scrollbar from '../../components/scrollbar';
// sections
import { UserListHead, UserListToolbar } from '../../sections/@dashboard/user';
import { IMAGE_URL } from '../../utils/config';
import { updateUrlParams } from '../../utils/urlUtilis';
import { useMyContext } from '../provider';
import GenerateToastConfig from '../../components/toast-config/GenerateToastConfig';
import useResponsive from '../../hooks/useResponsive';
import DeleteModal from '../../components/deleteModal/DeleteModal';
import TanstackTable from '../../components/tanstackMUItable/TanstackTable';
import TanstackTableV8 from '../../components/tanstackMUItable/tanstackTableV8';

export default function UserPage() {
  const navigate = useNavigate();
  const location = useLocation();
  const queryParams = new URLSearchParams(location.search)
  const [page, setPage] = useState(parseInt(queryParams.get('page'), 10) || 1);
  const [opens, setOpens] = useState();
  const [order, setOrder] = useState('asc');
  const [selected, setSelected] = useState([]);
  const [orderBy, setOrderBy] = useState('name');
  const [filterName, setFilterName] = useState('');
  const [rowsPerPage, setRowsPerPage] = useState(parseInt(queryParams.get('limit'), 10) || 10);
  const [amenityList, setAmenityList] = React.useState([]);
  const [search, setsearch] = useState('');
  const [totalCount, setTotalCount] = useState(0);
  const [filters, setFilters] = useState({});
  const [isLoading, setIsLoading] = useState(true);

  const { i18 } = useMyContext();
  const isMobile = useResponsive('down', 'sm')
  const queryPrms = new URLSearchParams(location.search);
  const id = queryPrms.get("id")
  const catid = id

  const TABLE_HEAD = [
    { id: 'icon', label: i18?.LISTINGPAGE?.ICON || 'Icon', alignRight: false },
    { id: 'name', label: i18?.LISTINGPAGE?.CREATED_NAME || 'Created Name', alignRight: false },
    { id: 'createdAt', label: i18?.LISTINGPAGE?.CREATED_AT || 'Created At', alignRight: false },
    { id: 'updatedAt', label: i18?.LISTINGPAGE?.UPDATED_AT || 'Updated At', alignRight: false },
    { id: 'action', label: i18?.LISTINGPAGE?.ACTION || 'Action', alignRight: false },
  ];

  const fetchData = async () => {
    setIsLoading(true);
    try {
      let url = `module/admin/amenity/${catid}?_page=${page}&_limit=${rowsPerPage}`;
      // if (search) {
      //   url += `&search=${search}`;
      //   setPage(1);
      // }

      if (search) url += `&search=${search}`;
      Object.entries(filters).forEach(([key, value]) => {
        if (value) url += `&${key}=${value}`;
      });

      const res = await axios.get(url);
      if (res.status === 200) {
        setAmenityList(res.data.data.amenities);
        setTotalCount(res.data.data.totalCount);
      } else {
        GenerateToastConfig(res.data.message);
      }
    } catch (err) {
      GenerateToastConfig(err?.response?.data?.message);
    } finally {
      setIsLoading(false);
    }
  };
  useEffect(() => {
    fetchData();
  }, [page, rowsPerPage, order, orderBy, search, filters]);

  useEffect(() => {
    updateUrlParams({ page, limit: rowsPerPage });
  }, [page, rowsPerPage, search]);

  const ActionComponent = (cell) => {
    const value = cell?.getValue();
    const original = cell?.row?.original;
    const [anchorEl, setAnchorEl] = useState(null);
    const [menuRowId, setMenuRowId] = useState(null);

    const handleActionMenu = (event, rowId) => {
      setAnchorEl(event.currentTarget);
      setMenuRowId(rowId);
    };

    const handleActionMenuClose = () => {
      setAnchorEl(null);
      setMenuRowId(null);
    };

    return (
      <>
        <IconButton
          sx={{
            width: '37px',
            height: '37px',
            background: '#EBEBEB',
            color: 'black',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            borderRadius: '50%',
          }}
          onClick={(event) => handleActionMenu(event, value)}
        >
          <Iconify icon="mdi:dots-horizontal" />
        </IconButton>
        <Popover
          anchorEl={anchorEl}
          open={Boolean(anchorEl) && menuRowId === value}
          onClose={handleActionMenuClose}
          anchorOrigin={{ vertical: 'top', horizontal: 'left' }}
          transformOrigin={{ vertical: 'top', horizontal: 'right' }}
          PaperProps={{
            sx: { width: 140 },
          }}
        >
          <MenuItem onClick={() => handleformdata(value, original?.name, original?.desc, original?.icon)}>
            <Iconify icon={'carbon:edit'} sx={{ mr: 2 }} /> Edit
          </MenuItem>
          <MenuItem onClick={() => deleteModal(value)} sx={{ color: 'error.main' }}>
            <Iconify icon={'eva:trash-2-outline'} sx={{ mr: 2 }} /> Delete
          </MenuItem>
        </Popover>
      </>
    );
  }

  const columns = [
    {
      header: i18?.LISTINGPAGE?.ICON || 'Icon',
      id: "icon",
      accessorKey: "icon",
      cell: ({ row }) => (
        row?.original?.icon ? <Avatar variant="square" src={IMAGE_URL + row?.original?.icon} sx={{ width: 40, height: 40 }} /> : "---"
      )
    },
    {
      header: i18?.LISTINGPAGE?.CREATED_NAME || 'Created Name',
      id: "name",
      accessorKey: "name",
      showFilter: true,
      cell: ({ row }) => <span>{row?.original?.name || '---'}</span>,
    },
    {
      header: i18?.LISTINGPAGE?.CREATED_AT || 'Created At',
      id: "createdAt",
      accessorKey: "createdAt",
      cell: ({ row }) => <span>{DateFormat(row?.original?.createdAt) || '---'}</span>,
    },
    {
      header: i18?.LISTINGPAGE?.UPDATED_AT || 'Updated At',
      id: "updatedAt",
      accessorKey: "updatedAt",
      cell: ({ row }) => <span>{DateFormat(row?.original?.updatedAt) || '---'}</span>,
    },
    {
      header: i18?.SETTINGSLIST?.ACTION || "Action",
      id: "action",
      accessorKey: "_id",
      cell: ActionComponent,
    },
  ]

  // const columns = useMemo(() => COLUMNS, []);
  // const data = React.useMemo(() => amenityList.map((user) => {
  //   return {
  //     icon: user?.icon,
  //     name: user?.name,
  //     desc: user?.desc,
  //     createdAt: user?.createdAt,
  //     updatedAt: user?.updatedAt,
  //     action: user?._id,
  //   };
  // }), [amenityList]);

  if (!location && !location?.state)
    return null
  const { cate } = location?.state || { cate: '' };
  const handleformdata = async (ids, cat, des, file) => {
    const type = 'Amenity Data';
    const action = 'Edit';

    navigate(`/dashboard/editamenitydata/${ids}`, {
      state: { process: action, types: type, id: ids, categories: cat, catid, descs: des, icon: file, cate },
    });
  };

  const deleteModal = (ids) => {
    sessionStorage.setItem("userId", ids);
    setOpens(true);
  }

  const deleteAmenity = async () => {
    const ids = sessionStorage.getItem("userId");
    try {
      const res = await axios.delete(`module/admin/amenity/${ids}`);
      if (res.status === 200) {
        setOpens(false)
        GenerateToastConfig(res.data.message, 'info');
        fetchData();
      } else {
        GenerateToastConfig(res.data.message);
      }
    } catch (err) {
      GenerateToastConfig(err?.response?.data?.message);
    }
  };

  const handleRequestSort = (event, property) => {
    const isAsc = orderBy === property && order === 'asc';
    setOrder(isAsc ? 'desc' : 'asc');
    setOrderBy(property);
  };

  const handleSelectAllClick = (event) => {
    if (event.target.checked) {
      const newSelecteds = amenityList.map((n) => n.name);
      setSelected(newSelecteds);
      return;
    }
    setSelected([]);
  };

  const handleOpenModal = () => {
    const type = 'Amenity Data';
    const action = 'Add';
    const id = catid;
    navigate('/dashboard/addamenity', { state: { types: type, process: action, ids: id, categories: cate } });
  };

  const handleChangePage = (event, newPage) => {
    setPage(newPage + 1);
  };

  const handleChangeRowsPerPage = (event) => {
    setPage(1);
    setRowsPerPage(parseInt(event.target.value, 10));
  };

  const handleFilterByName = (event) => {
    setPage(0);
    setFilterName(event.target.value);
  };


  const handleFilterChange = (filterKey, value) => {
    setFilters((prev) => ({ ...prev, [filterKey]: value }));
    setPage(1);
  };

  const backToRoute = () => {
    navigate('/dashboard/amenitycategory')
  };

  return (
    <>
      <Helmet>
        <title> {`List Amenity | Admin panel`} </title>
      </Helmet>

      {isMobile && <Stack direction='row' alignItems="center" style={{ marginBottom: "30px" }} justifyContent="space-between">
        <Box sx={{ display: 'flex', alignItems: 'center' }}>
          <Box
            sx={{
              width: '37px',
              height: '37px',
              background: '#FF5A60',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              borderRadius: '50%',
              cursor: 'pointer',
            }}
            onClick={backToRoute}
          >
            <Iconify icon={'mdi:arrow-left'} width={24} height={24} color="white" />
          </Box>
          <Typography variant="h4" gutterBottom sx={{ margin: '0px 0px 0px 10px', paddingBottom: '0px' }}>
            {i18?.LISTINGPAGE?.LIST_AMENITY_DATA || "List Amenity Data"}
          </Typography>
        </Box>
        <Button variant="contained" onClick={handleOpenModal} startIcon={<Iconify icon="eva:plus-fill" />}>
          {i18?.LISTINGPAGE?.ADD_AMENITY_DATA || "Add Amenity Data"}
        </Button>
      </Stack>}

      {!isMobile && <Stack direction="row" alignItems="center" justifyContent="space-between" mb={0}>
        <Stack direction='row' alignItems="center">
          <Box sx={{ display: 'flex', alignItems: 'center' }}>
            <Box
              sx={{
                width: '37px',
                height: '37px',
                background: '#FF5A60',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                borderRadius: '50%',
                cursor: 'pointer',
              }}
              onClick={backToRoute}
            >
              <Iconify icon={'mdi:arrow-left'} width={24} height={24} color="white" />
            </Box>
            <Typography variant="h4" gutterBottom sx={{ margin: '0px 0px 0px 10px', paddingBottom: '0px' }}>
              {i18?.LISTINGPAGE?.LIST_AMENITY_DATA || "List Amenity Data"}
            </Typography>
          </Box>
        </Stack>

        <Stack direction='row' alignItems="center">
          <UserListToolbar
            numSelected={selected.length}
            filterName={filterName}
            onFilterName={handleFilterByName}
            search={search}
            setsearch={setsearch}
          />
          <Button variant="contained" onClick={handleOpenModal} startIcon={<Iconify icon="eva:plus-fill" />}>
            {i18?.LISTINGPAGE?.ADD_AMENITY_DATA || "Add Amenity Data"}
          </Button>
        </Stack>

      </Stack>}

      <Card>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          {isMobile && <UserListToolbar
            numSelected={selected.length}
            filterName={filterName}
            onFilterName={handleFilterByName}
            search={search}
            setsearch={setsearch}
          />}
        </div>
        <Scrollbar>
          {/* <TanstackTable data={data} columns={columns} /> */}
          <TanstackTableV8
            data={amenityList}
            columns={columns}
            filters={filters}
            isLoading={isLoading}
            onFilterChange={handleFilterChange}
          />
        </Scrollbar>


        <DeleteModal
          isDeleteOpen={opens}
          handleClose={() => setOpens(false)}
          handleDelete={deleteAmenity}
        />

      </Card>

      <TablePagination
        rowsPerPageOptions={[5, 10, 25]}
        component="div"
        count={totalCount || '0'}
        rowsPerPage={rowsPerPage}
        page={page - 1}
        onPageChange={handleChangePage}
        onRowsPerPageChange={handleChangeRowsPerPage}
        sx={{
          '.MuiTablePagination-selectLabel': {
            marginTop: '12px',
          },
          '.MuiTablePagination-displayedRows': {
            marginTop: '12px',
          },
          '.MuiTablePagination-actions': {
            marginBottom: '6px',
          }
        }}
      />
    </>
  );
}


